// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// UpdateBudgets Set several budgets at once
	// (PUT /budgets)
	UpdateBudgets(ctx context.Context, request UpdateBudgetsRequestObject) (UpdateBudgetsResponseObject, error)
	// ListCategories List categories
	// (GET /categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// CreateCategory Create a category
	// (POST /categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// ReorderCategories Reorder categories
	// (PUT /categories/order)
	ReorderCategories(ctx context.Context, request ReorderCategoriesRequestObject) (ReorderCategoriesResponseObject, error)
	// DeleteCategory Delete a category
	// (DELETE /categories/{id})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// UpdateCategory Update a category
	// (PATCH /categories/{id})
	UpdateCategory(ctx context.Context, request UpdateCategoryRequestObject) (UpdateCategoryResponseObject, error)
	// SuggestCategory Suggest a category for a manual entry
	// (POST /categorization/suggest)
	SuggestCategory(ctx context.Context, request SuggestCategoryRequestObject) (SuggestCategoryResponseObject, error)
	// DeleteDevice Remove a push device
	// (DELETE /devices/{device_id})
	DeleteDevice(ctx context.Context, request DeleteDeviceRequestObject) (DeleteDeviceResponseObject, error)
	// RegisterDevice Register or refresh a push device
	// (PUT /devices/{device_id})
	RegisterDevice(ctx context.Context, request RegisterDeviceRequestObject) (RegisterDeviceResponseObject, error)
	// ListGoals List goals
	// (GET /goals)
	ListGoals(ctx context.Context, request ListGoalsRequestObject) (ListGoalsResponseObject, error)
	// CreateGoal Create a goal
	// (POST /goals)
	CreateGoal(ctx context.Context, request CreateGoalRequestObject) (CreateGoalResponseObject, error)
	// DeleteGoal Delete a goal
	// (DELETE /goals/{id})
	DeleteGoal(ctx context.Context, request DeleteGoalRequestObject) (DeleteGoalResponseObject, error)
	// GetGoal Get a goal
	// (GET /goals/{id})
	GetGoal(ctx context.Context, request GetGoalRequestObject) (GetGoalResponseObject, error)
	// UpdateGoal Update a goal
	// (PATCH /goals/{id})
	UpdateGoal(ctx context.Context, request UpdateGoalRequestObject) (UpdateGoalResponseObject, error)
	// ListContributions List a goal's contributions
	// (GET /goals/{id}/contributions)
	ListContributions(ctx context.Context, request ListContributionsRequestObject) (ListContributionsResponseObject, error)
	// CreateContribution Top up or withdraw from a goal
	// (POST /goals/{id}/contributions)
	CreateContribution(ctx context.Context, request CreateContributionRequestObject) (CreateContributionResponseObject, error)
	// DeleteContribution Delete a contribution
	// (DELETE /goals/{id}/contributions/{cid})
	DeleteContribution(ctx context.Context, request DeleteContributionRequestObject) (DeleteContributionResponseObject, error)
	// GetHome Get the Home screen
	// (GET /home)
	GetHome(ctx context.Context, request GetHomeRequestObject) (GetHomeResponseObject, error)
	// CreateImport Start a statement import
	// (POST /imports)
	CreateImport(ctx context.Context, request CreateImportRequestObject) (CreateImportResponseObject, error)
	// DeleteImport Discard an import
	// (DELETE /imports/{id})
	DeleteImport(ctx context.Context, request DeleteImportRequestObject) (DeleteImportResponseObject, error)
	// GetImport Get an import
	// (GET /imports/{id})
	GetImport(ctx context.Context, request GetImportRequestObject) (GetImportResponseObject, error)
	// CommitImport Write the included rows to the ledger
	// (POST /imports/{id}/commit)
	CommitImport(ctx context.Context, request CommitImportRequestObject) (CommitImportResponseObject, error)
	// SetImportMapping Supply the column mapping for an import
	// (PUT /imports/{id}/mapping)
	SetImportMapping(ctx context.Context, request SetImportMappingRequestObject) (SetImportMappingResponseObject, error)
	// ListImportRows List an import's rows for review
	// (GET /imports/{id}/rows)
	ListImportRows(ctx context.Context, request ListImportRowsRequestObject) (ListImportRowsResponseObject, error)
	// UpdateImportRow Edit an import row
	// (PATCH /imports/{id}/rows/{row_id})
	UpdateImportRow(ctx context.Context, request UpdateImportRowRequestObject) (UpdateImportRowResponseObject, error)
	// ListInsights Insight cards for a period
	// (GET /insights)
	ListInsights(ctx context.Context, request ListInsightsRequestObject) (ListInsightsResponseObject, error)
	// DeleteMe Delete the account
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe Get the current user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update the current user
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// ListNotifications List notifications
	// (GET /notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// MarkNotificationsRead Mark notifications as read
	// (POST /notifications/read)
	MarkNotificationsRead(ctx context.Context, request MarkNotificationsReadRequestObject) (MarkNotificationsReadResponseObject, error)
	// CreateReceipt Start a receipt scan
	// (POST /receipts)
	CreateReceipt(ctx context.Context, request CreateReceiptRequestObject) (CreateReceiptResponseObject, error)
	// DeleteReceipt Discard a receipt
	// (DELETE /receipts/{id})
	DeleteReceipt(ctx context.Context, request DeleteReceiptRequestObject) (DeleteReceiptResponseObject, error)
	// GetReceipt Get a receipt
	// (GET /receipts/{id})
	GetReceipt(ctx context.Context, request GetReceiptRequestObject) (GetReceiptResponseObject, error)
	// ConfirmReceipt Save a receipt as an expense
	// (POST /receipts/{id}/confirm)
	ConfirmReceipt(ctx context.Context, request ConfirmReceiptRequestObject) (ConfirmReceiptResponseObject, error)
	// GetCategoriesSummary Spending per category for a period
	// (GET /summary/categories)
	GetCategoriesSummary(ctx context.Context, request GetCategoriesSummaryRequestObject) (GetCategoriesSummaryResponseObject, error)
	// GetCategorySummary One category's spending and trend for a period
	// (GET /summary/categories/{id})
	GetCategorySummary(ctx context.Context, request GetCategorySummaryRequestObject) (GetCategorySummaryResponseObject, error)
	// GetStatsSummary Total spending, series and breakdown for a period
	// (GET /summary/stats)
	GetStatsSummary(ctx context.Context, request GetStatsSummaryRequestObject) (GetStatsSummaryResponseObject, error)
	// ListTransactions List transactions
	// (GET /transactions)
	ListTransactions(ctx context.Context, request ListTransactionsRequestObject) (ListTransactionsResponseObject, error)
	// CreateTransaction Create a transaction
	// (POST /transactions)
	CreateTransaction(ctx context.Context, request CreateTransactionRequestObject) (CreateTransactionResponseObject, error)
	// DeleteTransaction Delete a transaction
	// (DELETE /transactions/{id})
	DeleteTransaction(ctx context.Context, request DeleteTransactionRequestObject) (DeleteTransactionResponseObject, error)
	// GetTransaction Get a transaction
	// (GET /transactions/{id})
	GetTransaction(ctx context.Context, request GetTransactionRequestObject) (GetTransactionResponseObject, error)
	// UpdateTransaction Update a transaction
	// (PATCH /transactions/{id})
	UpdateTransaction(ctx context.Context, request UpdateTransactionRequestObject) (UpdateTransactionResponseObject, error)
	// CreateUpload Request a presigned upload
	// (POST /uploads)
	CreateUpload(ctx context.Context, request CreateUploadRequestObject) (CreateUploadResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

